def transform(pixels):
    result = []
    for r, g, b in pixels:
        if r < 85:
            result.append([255, 255, 255])
        elif False:  # Is red above 150?
            result.append([r, g, min(255, b + 50)])
        else:
            result.append([r, g, b])
    return result

pixels = [[20,30,40],[200,40,30],[120,180,90]]
colors = transform(pixels)
